# Login to phone + fetch alarms, build mapping from coworker first-name to alarm_id
pw_phone = [a['password'] for a in apis.supervisor.show_account_passwords() if a['account_name']=='phone'][0]
phone_login = apis.phone.login(username='3947324235', password=pw_phone)
access_token_phone = phone_login['access_token']

alarms=[]
page_index=0
page_limit=20
while True:
    page = apis.phone.show_alarms(access_token=access_token_phone, page_index=page_index, page_limit=page_limit)
    if not page:
        break
    alarms.extend(page)
    page_index += 1

# Filter to work meeting alarms: enabled and label starts with 'One-on-One with '
work_alarm_map = {}
for a in alarms:
    label = a.get('label')
    if not label:
        continue
    if label.startswith('One-on-One with '):
        person = label.replace('One-on-One with ', '').strip()
        work_alarm_map[person] = a

# Print enabled meeting alarms
enabled_work_alarms = {p: a for p,a in work_alarm_map.items() if a.get('enabled')}
print('Total one-on-one alarms:', len(work_alarm_map))
print('Enabled one-on-one alarms:', len(enabled_work_alarms))
for p,a in sorted(enabled_work_alarms.items(), key=lambda x: x[0].lower()):
    print('person=', p, 'alarm_id=', a['alarm_id'], 'label=', a['label'], 'enabled=', a.get('enabled'))

# Also list non-one-on-one work alarms (standup)
for a in alarms:
    if a.get('label') == 'Weekly Work Standup Meeting':
        print('Standup alarm:', a['alarm_id'], 'enabled=', a.get('enabled'), 'days=', a.get('repeat_days'), 'time=', a.get('time'))

